from neo4j import GraphDatabase
from datetime import datetime
import pandas as pd
import Config as config
import time
from itertools import islice

NEO_IP = "XXX.XXX.XXX.XXX"
NEO_PORT = "7687"

BATCH_SIZE = 100

specific_date = config.PARAMS["Todate"]

driver = GraphDatabase.driver(f"bolt://{NEO_IP}:{NEO_PORT}", encrypted=False)

def insert_event_batch(tx, events):
    query = """
        UNWIND $events AS event
        MATCH (n:node)
        WHERE n.CalendarEvent IS NULL AND n.Date = $specific_date
        SET n.CalendarEvent = event.cal_event
        RETURN COUNT(n) AS updated_count
        """
    tx.run(query, events=events, specific_date=specific_date)

def chunked_iterable(iterable, size):
    iterator = iter(iterable)
    for first in iterator:
        yield [first, *islice(iterator, size - 1)]

def process_events(data, batch_size):
    with driver.session() as session:
        for entry in data:
            cal_event = entry["cal_event"]
            events = [{"cal_event": cal_event} for _ in entry["dates"] if _ == specific_date]

            if not events:
                continue  # Skip if no matching events

            for batch in chunked_iterable(events, batch_size):
                session.write_transaction(insert_event_batch, batch)

